package io.github.diodeme.ji.ai;

import java.util.Map;

/** JSON-schema-shaped tool declaration without a serialization-framework dependency. */
public record ToolSchema(String name, String description, Map<String, Object> inputSchema) {
    public ToolSchema {
        if (name == null || name.isBlank()) throw new IllegalArgumentException("tool name must not be blank");
        if (description == null) throw new IllegalArgumentException("tool description must not be null");
        inputSchema = Map.copyOf(inputSchema);
    }
}
